{
  "category_edits": [
    {
      "category": "training_strategy",
      "rationale": "Apply epoch-wise cosine learning-rate decay to all four category models, retaining the existing initial rate and reaching 20% after 200 epochs. Preserve Adam, early stopping, model architecture, loss, seeds, and prediction behavior.",
      "edits": [
        {
          "find": "    scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(\n        optimizer, mode=\"max\", factor=0.5, patience=1,\n        threshold=0.0, threshold_mode=\"abs\", min_lr=LR * 0.125\n    )",
          "replace": "    scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(\n        optimizer, T_max=200, eta_min=LR * 0.2\n    )"
        },
        {
          "find": "        avg_loss = total_loss / max(NUM_BATCHES, 1)\n        if epoch % EVAL_EVERY == 0 or epoch == NUM_EPOCHS:",
          "replace": "        avg_loss = total_loss / max(NUM_BATCHES, 1)\n        scheduler.step()\n        if epoch % EVAL_EVERY == 0 or epoch == NUM_EPOCHS:"
        },
        {
          "find": "            hr10 = val_m[\"HR@10\"]\n            scheduler.step(hr10)\n",
          "replace": "            hr10 = val_m[\"HR@10\"]\n"
        }
      ]
    }
  ],
  "change_summary": "Replace validation-triggered plateau scheduling with per-epoch cosine decay from LR to 0.2 × LR over 200 epochs."
}
